    /// The instructions of the reserved group.
    fn operands_reserved(&self) -> Operands {
        let this = *self;
        match this {
            Instruction::UdfOnlyPermUndef { imm } => Operands::of([Operand::Imm {
                value: imm.value(),
                modifier: None,
            }]),
            _ => unreachable!("an instruction of another group"),
        }
    }

